 "nangLucJson": "{\n  \"sprintTruoc\": { \"ten\": \"Sprint 2 (iteration 2)\", \"ngayLamViec\": 15, \"nguoi\": 5, \"ngayVang\": 3, \"ngayDieuPhoi\": 4.5, \"diemXong\": 41 },\n  \"sprint\": { \"ten\": \"Sprint 3 (iteration 3, phần 1)\", \"batDau\": \"2027-03-08\", \"ketThuc\": \"2027-03-26\",\n    \"vang\": { \"C1\": [\"2027-03-19\"], \"C4\": [\"2027-03-24\", \"2027-03-25\"] },\n    \"dieuPhoi\": { \"C1\": 0.3 },\n    \"nhomMuon\": \"làm hết 18 ticket còn lại của iteration 3\" }\n}",
